export type Cell = [number, number];

type CellKey = string;

const keyOf = ([x, y]: Cell): CellKey => `${x},${y}`;

const cellOf = (key: CellKey): Cell => {
  const [x, y] = key.split(",").map(Number);
  return [x, y];
};

function neighborsOf([x, y]: Cell): Cell[] {
  return [-1, 0, 1].flatMap((dx) =>
    [-1, 0, 1]
      .filter((dy) => !(dx === 0 && dy === 0))
      .map((dy): Cell => [x + dx, y + dy]),
  );
}

function countLiveNeighbors(cell: Cell, liveCells: Set<CellKey>): number {
  return neighborsOf(cell).filter((neighbor) => liveCells.has(keyOf(neighbor)))
    .length;
}

function cellsToEvaluate(cells: Cell[]): Cell[] {
  const keys = cells.flatMap((cell) => [
    keyOf(cell),
    ...neighborsOf(cell).map(keyOf),
  ]);
  return [...new Set(keys)].map(cellOf);
}

function isAliveNextGeneration(cell: Cell, liveCells: Set<CellKey>): boolean {
  const liveNeighborCount = countLiveNeighbors(cell, liveCells);
  if (liveCells.has(keyOf(cell))) {
    return liveNeighborCount === 2 || liveNeighborCount === 3;
  }
  return liveNeighborCount === 3;
}

export function nextGeneration(cells: Cell[]): Cell[] {
  const liveCells = new Set(cells.map(keyOf));
  return cellsToEvaluate(cells).filter((cell) =>
    isAliveNextGeneration(cell, liveCells),
  );
}
